mapper.select:
select
    s.*,
    p.park_name
from spaces s
left join parking p on p.id = s.park_id
where park_name = #{parkName}
  and spaces_row =#{spacesRow}
  and spaces_col=#{spacesCol}
  and spaces_storey=#{spacesStorey}

mapper.update:
update spaces
set update_time =now(),user_name = #{userName}
where id = #{spacesId}

mapper.select:
select s.*, p.park_name from spaces s left join parking p on s.park_id = p.id
park_id=#{parkId} and spaces_storey=#{spacesStorey}
and spaces_name like concat('%', #{spacesName}, '%')
